/**
 * The same cart after the discount engine has brought it to 0 kr, which is when the `ZeroAmount` payment
 * provider is used. Every line keeps its original amount in `amountBeforeDiscounts` and is priced at 0.
 */
const zeroAmountCartResponse = (cartId: string): CartResponseV2 => {
  const cart = cartResponse(cartId);
  const zero = { amountIncludingVat: 0, vatAmount: 0 };
  return {
    ...cart,
    cartPrice: { amount: zero, amountBeforeDiscounts: cart.cartPrice.amount },
    cartItems: cart.cartItems.map((item) => ({
      ...item,
      price: { ...item.price, amount: zero, amountBeforeDiscounts: item.price.amount },
    })),
  };
};

