/**
 * The real service with `getCart` and `getPaymentStatus` answered from mock data. Pass a function override for
 * a payment call that has to behave differently, e.g. a finalize that fails or a payment that changes state.
 */
const mockCheckoutService = (
  cartId: string,
  {
    cart = cartResponse(cartId),
    payment,
    ...overrides
  }: Partial<Pick<ICheckoutService, "getPaymentStatus" | "finalizeKlarnaOrder">> & {
    /** The cart `getCart` answers with. Defaults to the full-price mock cart. */
    cart?: CartResponseV2;
    /** The payment `getPaymentStatus` answers with. Leave it out only when overriding `getPaymentStatus`. */
    payment?: GetPaymentResponse;
  } = {},
): ICheckoutService => ({
  ...CheckoutService,
  getCart: async () => {
    action("getCart")(cartId);
    await delay(100);
    return cart;
  },
  getPaymentStatus: payment
    ? async () => {
        action("getPaymentStatus")(cartId, payment.paymentState);
        await delay(200);
        return payment;
      }
    : async () => {
        // Falling back to the real service would put a live payment request in the story.
        throw new Error("mockCheckoutService: pass either `payment` or a `getPaymentStatus` override");
      },
  ...overrides,
});

