/**
 * `AuthAware` calls MyParks on mount and MyParksService is not configured in Storybook, so its calls are
 * stubbed from `render`, before the component mounts (as in `login-or-register.stories.tsx`).
 */
const mockMyParksService = (isLoggedIn: boolean) => {
  MyParksService.fetchSession = async () => {
    action("fetchSession")({ isLoggedIn });
    await delay(200);
    if (!isLoggedIn) {
      throw new Error("No session");
    }
    return {
      antiCsrfToken: "mocked-token",
      cookieString: "storybook-session-cookie",
      hasLoggedIn: true,
      user: storybookUser,
    };
  };
  MyParksService.getUser = async () => {
    action("getUser")();
    await delay(200);
    if (!isLoggedIn) {
      throw new Error("No session");
    }
    return { ...storybookUser, contactMethods: [] };
  };
  MyParksService.fetchProducts = async () => {
    action("fetchProducts")();
    await delay(200);
    if (!isLoggedIn) {
      throw new Error("No session");
    }
    // No `webOrders` entry for ORDER_ID, so `usePollForOrderInAuth` keeps polling.
    return emptyUserProducts;
  };
};

