    await waitFor(() => expect(canvas.getByTestId("klarna-html-snippet")).toBeInTheDocument(), { timeout: 5000 });
    await expect(canvas.getByText("Entré Kväll 10-64 år")).toBeInTheDocument();
    await expect(canvas.getByText("Mottagare: mottagaren@example.com")).toBeInTheDocument();
    await expect(canvas.getByText("Tidsinställt: 2026-09-25 kl 15:44")).toBeInTheDocument();
