/**
 * Mirrors the backend: the payment reads as `Initialized` until the Klarna order is finalized, then as
 * `Paid`. A mock that kept answering `Initialized` would loop - `KlarnaCheckout` refetches the payment on
 * mount, "not paid" triggers another finalize, which mounts `KlarnaCheckout` again.
 */
const finalizeFlow = (() => {
  let isFinalized = false;
  return {
    reset: () => {
      isFinalized = false;
    },
    service: mockCheckoutService(cartIds.finalizing, {
      getPaymentStatus: async () => {
        action("getPaymentStatus")(cartIds.finalizing, { isFinalized });
        await delay(200);
        return klarnaPayment(cartIds.finalizing, isFinalized ? PaymentState.PAID : PaymentState.INITIALIZED);
      },
      finalizeKlarnaOrder: async (cartId, klarnaOrderId) => {
        action("finalizeKlarnaOrder")(cartId, klarnaOrderId);
        await delay(600);
        isFinalized = true;
        return klarnaPayment(cartIds.finalizing, PaymentState.PAID);
      },
    }),
  };
})();

/** The visitor comes back from Klarna with a payment that is not `Paid` yet, so the order is finalized first. */
export const FinalizingKlarnaPayment: Story = {
  // Start from "not finalized yet" on every (re)mount.
  beforeEach: () => {
    finalizeFlow.reset();
  },
  args: {
    cartId: cartIds.finalizing,
    resetQueryKeys: shopServiceQueryKeysToReset(cartIds.finalizing),
    checkoutService: finalizeFlow.service,
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    await waitFor(() => expect(canvas.getByText("Din beställning")).toBeInTheDocument(), { timeout: 5000 });
    await waitFor(() => expect(canvas.getByTestId("klarna-html-snippet")).toBeInTheDocument(), { timeout: 5000 });
  },
};

/** Finalizing the Klarna order fails, so the generic checkout error message is shown instead. */
export const FinalizeKlarnaPaymentFails: Story = {
  args: {
    cartId: cartIds.finalizeError,
    resetQueryKeys: shopServiceQueryKeysToReset(cartIds.finalizeError),
    checkoutService: mockCheckoutService(cartIds.finalizeError, {
      payment: klarnaPayment(cartIds.finalizeError, PaymentState.INITIALIZED),
      finalizeKlarnaOrder: async (cartId, klarnaOrderId) => {
        action("finalizeKlarnaOrder")(cartId, klarnaOrderId);
        await delay(200);
        // Must be a recognised server error shape - anything else is retried three times by `retryLogic`.
        throw { status: 400, error: { error: InitializePaymentErrorCode.INVALID_CART_STATE } };
      },
    }),
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    await waitFor(() => expect(canvas.getByText(/^Något gick fel/)).toBeInTheDocument(), { timeout: 5000 });
    await expect(canvas.queryByTestId("klarna-html-snippet")).toBeNull();
  },
};

