/**
 * A logged in visitor whose order has not reached MyParks. The mocked session never returns the order, so
 * `usePollForOrderInAuth` polls for its full minute and the "Slutför köp..." card stays on top of the
 * confirmation the whole time. The story is the waiting state - it never resolves.
 */
export const WaitingForOrderThatNeverArrives: Story = {
  args: {
    cartId: cartIds.waitingForOrder,
    isLoggedIn: true,
    resetQueryKeys: shopServiceQueryKeysToReset(cartIds.waitingForOrder),
    checkoutService: mockCheckoutService(cartIds.waitingForOrder, {
      payment: klarnaPayment(cartIds.waitingForOrder, PaymentState.PAID),
    }),
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    // The card is up from the first render, so wait for the snippet (payment loaded) before checking it stayed.
    await waitFor(() => expect(canvas.getByTestId("klarna-html-snippet")).toBeInTheDocument(), { timeout: 5000 });
    await expect(canvas.getByText("Slutför köp...")).toBeInTheDocument();
    await expect(canvas.getByTestId("checkout-loading")).toBeInTheDocument();
  },
};

/**
 * A cart the discount engine has brought to 0 kr is paid through the `ZeroAmount` provider, which has no
 * confirmation UI of its own, so only the order summary is shown: every line at 0 kr with its original
 * price struck through, and a total of 0 kr.
 */
export const ZeroAmount: Story = {
  args: {
    cartId: cartIds.zeroAmount,
    resetQueryKeys: shopServiceQueryKeysToReset(cartIds.zeroAmount),
    checkoutService: mockCheckoutService(cartIds.zeroAmount, {
      cart: zeroAmountCartResponse(cartIds.zeroAmount),
      payment: zeroAmountPayment(cartIds.zeroAmount),
    }),
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    await waitFor(() => expect(canvas.getByText("Din beställning")).toBeInTheDocument(), { timeout: 5000 });
    // One struck-through original price per cart item.
    await expect(canvasElement.querySelectorAll("s")).toHaveLength(4);
    await expect(canvas.getByText("Avdragen rabatt")).toBeInTheDocument();
    // Currency formatting uses non-breaking spaces, hence the loose whitespace match.
    await expect(within(canvas.getByTestId("summary-total")).getByText(/^0\s*kr$/)).toBeInTheDocument();
    // The "Slutför köp..." card is up until the payment has loaded and the visitor is known to be logged out.
    await waitFor(() => expect(canvas.queryByText("Slutför köp...")).toBeNull(), { timeout: 5000 });
    await expect(canvas.queryByTestId("klarna-html-snippet")).toBeNull();
  },
};
